import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';

const HomePage = () => {
  const [lorries, setLorries] = useState([]);

  useEffect(() => {
    // Fetch lorry details from the backend API
    const fetchLorries = async () => {
      try {
        const response = await fetch('/api/lorries'); // Adjust the API endpoint as needed
        const data = await response.json();
        setLorries(data);
      } catch (error) {
        console.error('Error fetching lorries:', error);
      }
    };

    fetchLorries();
  }, []);

  return (
    <HomePageContainer>
      <ContactNumber>Contact: 9443769338</ContactNumber>
      <Header>Sri-Murugan Rig Service</Header>
      <CardContainer>
        {lorries.map((lorry) => (
          <Card key={lorry.id}>
            <CardHeader>{lorry.ownerName}</CardHeader>
            <OwnerPic src={lorry.ownerPic} alt={`${lorry.ownerName}`} />
            <CardBody>
              <p>Registration Number: {lorry.registrationNumber}</p>
              <DashboardLink to={`/dashboard/${lorry.registrationNumber}`}>
                Go to Dashboard
              </DashboardLink>
            </CardBody>
          </Card>
        ))}
      </CardContainer>
    </HomePageContainer>
  );
};

export default HomePage;
